<?php
namespace App\Http\Controllers;
use App\Models\PayrollLine; use App\Models\PayrollRun; use App\Models\StatutoryRateProfile; use App\Services\PayrollCalculationService; use App\Services\WorkforceAuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class PayrollController extends Controller { public function index(){ $runs=PayrollRun::query()->latest('year')->latest('month')->paginate(20); return view('workforce.payroll.index',compact('runs')); }
public function createRun(Request $r, PayrollCalculationService $calc, WorkforceAuditService $audit){$d=$r->validate(['year'=>'required|integer|min:2020|max:2100','month'=>'required|integer|min:1|max:12','statutory_rate_profile_id'=>'required|exists:statutory_rate_profiles,id']);$run=PayrollRun::firstOrCreate(['year'=>$d['year'],'month'=>$d['month']],['name'=>sprintf('Payroll %04d-%02d',$d['year'],$d['month']),'status'=>'draft','statutory_rate_profile_id'=>$d['statutory_rate_profile_id'],'prepared_by'=>auth()->id()]); if($run->is_locked) abort(409,'Finalized payroll is locked.');$rates=StatutoryRateProfile::findOrFail($d['statutory_rate_profile_id']);$employees=DB::table('employees')->where('is_active',true)->pluck('id');foreach($employees as $eid){try{$p=$calc->calculate((int)$eid,$d['year'],$d['month'],$rates);PayrollLine::updateOrCreate(['payroll_run_id'=>$run->id,'employee_id'=>$eid],['contract_id'=>$p['contract']->id,'cost_centre_id'=>$p['contract']->cost_centre_id,'basic_salary'=>$p['basic'],'allowances'=>$p['allowances'],'overtime_amount'=>$p['overtime'],'locum_amount'=>$p['locum'],'gross_pay'=>$p['gross'],'epf_employee'=>$p['epfEmployee'],'epf_employer'=>$p['epfEmployer'],'etf_employer'=>$p['etfEmployer'],'apit'=>$p['apit'],'other_deductions'=>$p['deductions'],'net_pay'=>$p['net'],'calculation_snapshot'=>$p['snapshot']]);}catch(\Throwable $e){}}$audit->model('updated',$run,'Payroll calculated/recalculated');return back()->with('success','Payroll calculated. Review exceptions and APIT configuration before approval.');}
public function finalize(PayrollRun $run, WorkforceAuditService $audit){if($run->is_locked) return back();$old=$run->toArray();$run->update(['status'=>'finalized','approved_by'=>auth()->id(),'approved_at'=>now(),'finalized_at'=>now(),'is_locked'=>true]);$audit->model('updated',$run,'Payroll finalized and locked',$old);return back()->with('success','Payroll finalized and locked.');}}